"use strict";
import LogoProvider from "components/Logo/LogoProvider";
import { useUnlockFlow } from "hooks/useUnlockFlow";
import { Lock } from "react-feather";
import { Link } from "react-router-dom";
import { Flex, SpinningLoader, StarBorderButton, Text, useSporeColors } from "ui/src";
import {
  calculateTimeUntilUnlock,
  formatABXAmount,
  formatTimeUntilUnlock,
  formatVotingPower
} from "utils/lockCalculations";
import IncreaseExtendMergeTransferReset from "./IncreaseExtendMergeTransferReset";
export default function SingleLock({ lock }) {
  const colors = useSporeColors();
  const { executeUnlock, isProcessing, flowState } = useUnlockFlow();
  const isLockExpired = !lock.permanent && calculateTimeUntilUnlock(lock.lockEnd).expired;
  const rowData = [
    {
      label: "Lock Type",
      value: lock.permanent ? "Permanent" : lock.managed ? "Managed" : "Standard"
    },
    {
      label: "Locked Amount",
      value: `${formatABXAmount(lock.amount)} ABX`
    },
    {
      label: "Voting Power",
      value: `${formatVotingPower(lock.votingPower)} veABX`
    },
    {
      label: "Unlock Date",
      value: lock.permanent ? "Permanent Lock" : formatTimeUntilUnlock(lock.lockEnd),
      isUnlockAction: isLockExpired
    }
  ];
  const lockContent = <Flex
    $platform-web={{ display: "grid", gridTemplateColumns: "2fr 1fr 1fr 1fr 1.5fr" }}
    $lg={{ gridTemplateColumns: "1fr", padding: "$spacing12", maxHeight: "none" }}
    p={"$spacing18"}
    borderRadius={"$rounded12"}
    gap={"$gap16"}
    borderWidth={1}
    borderColor={"$surface3"}
    transition="background-color 0.2s ease"
    {...!isLockExpired && {
      hoverStyle: {
        backgroundColor: "$surface1Hovered"
      }
    }}
    overflow="visible"
    position="relative"
    group
    minHeight={95}
  >
      <Flex
    $group-hover={{ opacity: 0 }}
    position="absolute"
    inset={0}
    borderRadius={"$rounded12"}
    height={"100%"}
    width={"100%"}
    transition="opacity 0.2s ease"
    style={{
      background: `linear-gradient(10deg, ${colors.surface1.variable} 0%, ${colors.slate.variable} 100%)`
    }}
  />
      <Flex className="left" row gap={"$gap12"} $lg={{ mb: "$spacing12" }}>
        <Flex
    height={50}
    width={50}
    centered
    borderRadius={"$rounded12"}
    borderWidth={1}
    borderColor={"$surface3"}
    row
    style={{
      background: `linear-gradient(90deg, ${colors.surface2Hovered.variable} 0%, ${colors.surface2.variable} 40%, ${colors.surface2Hovered.variable} 60%, ${colors.slate.variable} 100%)`
    }}
  >
          <LogoProvider color={colors.neutral2Temp.val} size={24} />
        </Flex>

        <Flex flexDirection="column" justifyContent="flex-start" gap={"$gap8"} flex={1}>
          <Flex row gap={"$gap12"} alignItems="center">
            <Text>Lock #{lock.id}</Text>
            <Flex>
              <Lock size={14} color={colors.neutral3.val} />
            </Flex>
          </Flex>

          <IncreaseExtendMergeTransferReset lockId={lock.id} isReadyToUnlock={isLockExpired} />
        </Flex>
      </Flex>

      {rowData.map((item) => <Flex
    key={item.label}
    className="rebase"
    gap={"$gap12"}
    flexDirection="column"
    justifyContent="flex-start"
    alignItems="flex-end"
    $lg={{
      borderTopWidth: 1,
      borderColor: "$surface3",
      py: "$spacing12",
      gap: 0,
      flexDirection: "row",
      alignItems: "center",
      justifyContent: "space-between"
    }}
  >
          <Text variant="body3" color={"$neutral2"}>
            {item.label}
          </Text>
          {item.isUnlockAction ? <StarBorderButton
    as="button"
    speed="3s"
    py={8}
    px={12}
    disabled={isProcessing}
    onClick={() => {
      executeUnlock(lock.id);
    }}
  >
              <Flex row alignItems="center" gap={"$gap8"}>
                {isProcessing && flowState.tokenId === lock.id && <SpinningLoader size={16} />}
                <Text variant="buttonLabel4" color="inherit">
                  {isProcessing && flowState.tokenId === lock.id ? "Unlocking" : "Unlock ABX"}
                </Text>
              </Flex>
            </StarBorderButton> : <Text variant="body3">{item.value}</Text>}
        </Flex>)}
    </Flex>;
  if (isLockExpired) {
    return lockContent;
  }
  return <Link to={`/locks/modify-lock?lockId=${lock.id}&tab=Increase`} className="text-decoration-none">
      {lockContent}
    </Link>;
}
